30	/// Root widget. Portrait-only, light-mode-only, fixed 390x844 frame — no
31	/// breakpoint, landscape or dark-mode path anywhere in the app (per the
32	/// epic's UX constraints).
33	///
34	/// Story 1.4 scope: `home` branches on `SessionRepository.statusStream`
35	/// instead of hardcoding `AuthScreen` — `restoreSession()` fires once at
36	/// boot (unconditional, no client-side expiry math) and the stream's first
37	/// emission decides whether the user lands on `AuthScreen` or the post-auth
38	/// placeholder. No `go_router` yet (Story 1.6): the `MaterialApp`/`Navigator`
39	/// shape is unchanged, and a successful signup/login still simply
40	/// pushes-replaces via `onAuthenticated`.
41	///
42	/// Story 1.5 scope: a mid-session expiry (the same stream's `expired`
43	/// value) never changes which screen `home` renders — `build()`'s
44	/// `StreamBuilder` branch below treats it identically to `authenticated`.
45	/// The only extra reaction is scheduling the `ConfirmationDialog` overlay
46	/// on top of that same screen, from inside that same (sole) subscription —
47	/// `SessionRepository.statusStream`'s real implementation is a broadcast
48	/// `Stream.multi`, but several existing tests mock it as a plain
49	/// single-subscription `Stream.value(...)`, so a *second* independent
50	/// `.listen()` here would break those by listening to it twice.
51	class CerneApp extends StatefulWidget {
52	  const CerneApp({super.key});
53	
54	  @override
55	  State<CerneApp> createState() => _CerneAppState();
56	}
57	
58	class _CerneAppState extends State<CerneApp> {
59	  late final SessionRepository _sessionRepository;
60	
61	  // Cached once: `SessionRepository.statusStream`'s getter builds a new
62	  // `Stream.multi` instance on every access (code review of
63	  // story-1-4-silent-session-refresh-persistence), so reading it straight
64	  // into `StreamBuilder.stream` on every `build()` would make it resubscribe
65	  // and lose its current status on each rebuild instead of staying on one
66	  // subscription for this widget's lifetime.
67	  late final Stream<SessionStatus> _statusStream;
68	
69	  // Code review of story-1-5: `ConfirmationDialog.isOpen` only guards
70	  // against a *second* overlay stacking while one is already showing — it
71	  // goes back to `false` the moment the first one closes. Nothing today
72	  // transitions `SessionStatus` away from `expired` once it's reached, so
73	  // without this separate flag, any later rebuild of `CerneApp` that still
74	  // observes `expired` (e.g. a hot reload, or a future dependency this
75	  // widget picks up) would call `ConfirmationDialog.show` again and reopen
76	  // the overlay on top of whatever the user already navigated to after
77	  // confirming it once.
78	  bool _expiryOverlayShown = false;
79	
80	  // One-shot guard for the overlay's own "Entrar novamente" confirm callback
81	  // (code review of story-1-5) — a rapid double-tap during the dialog's
82	  // 180ms exit fade must not fire the pop/push pair twice.
83	  bool _reauthRouteRequested = false;
84	
85	  @override
86	  void initState() {
87	    super.initState();
88	    _sessionRepository = sl<SessionRepository>();
89	    _statusStream = _sessionRepository.statusStream;
90	    // Fire-and-forget: the outcome reaches the UI through `statusStream`
91	    // below, not through this call's return value. `restoreSession()`
92	    // already maps every internal failure to `Left`/an `unauthenticated`
93	    // emission and never throws. This `catchError` is NOT a UI recovery
94	    // path — its handler's return value is discarded by `unawaited` and
95	    // never reaches `statusStream`, so it does not unblock `build()`'s
96	    // `_BootLoadingScreen` branch. It exists purely so a future regression
97	    // that broke the "never throws" contract above would surface as a
98	    // logged message instead of an unhandled zone exception.
99	    unawaited(
100	      _sessionRepository.restoreSession().catchError(_asUnauthenticated),
101	    );
102	  }
103	
104	  /// Story 1.5's whole reaction to an `expired` snapshot (I/O matrix —
105	  /// every other status is a no-op, since `SessionRepositoryImpl` already
106	  /// only ever emits `expired` from `authenticated`, and this is called
107	  /// from the same `StreamBuilder` subscription that renders the screen,
108	  /// not a second one).
109	  ///
110	  /// `showGeneralDialog` (inside `ConfirmationDialog.show`) pushes a route,
111	  /// which must never happen mid-`build()` — deferred to
112	  /// `addPostFrameCallback`. `_expiryOverlayShown` (not
113	  /// `ConfirmationDialog.isOpen`, which resets as soon as the overlay
114	  /// closes) makes this a one-shot per `expired` episode: nothing today
115	  /// transitions the status back out of `expired`, so without that guard a
116	  /// later rebuild would reopen an overlay the user already confirmed.
117	  void _maybeShowExpiryOverlay(BuildContext context, SessionStatus? status) {
118	    if (status != SessionStatus.expired || _expiryOverlayShown) {
119	      return;
120	    }
121	    _expiryOverlayShown = true;
122	    WidgetsBinding.instance.addPostFrameCallback((_) {
123	      if (!context.mounted) {
124	        return;
125	      }
126	      // Discarded deliberately, same as `restoreSession()`'s own call above —
127	      // any error surfaces as a logged message instead of an unhandled
128	      // Future rejection.
129	      unawaited(
130	        ConfirmationDialog.show(
131	          context: context,
132	          builder: (dialogContext) => ConfirmationDialog(
133	            icon: Icons.lock_outline,
134	            title: 'Sessão expirada',
135	            message:
136	                'Sua sessão expirou por segurança. Entre novamente para '
137	                'continuar — sua conversa continua aqui.',
138	            caption: 'o histórico e a posição do scroll são preservados',
139	            confirmLabel: 'Entrar novamente',
140	            barrierColor: DesignTokens.colorScrim,
141	            onConfirm: () {
142	              // One-shot guard against a rapid double-tap firing this twice
143	              // while the dialog's 180ms exit fade still leaves the button
144	              // hit-testable — without it, a second tap would race the
145	              // first `pop()`/`push()` pair and could push a duplicate
146	              // `_BiometricReauthPlaceholder`.
147	              if (_reauthRouteRequested) {
148	                return;
149	              }
150	              _reauthRouteRequested = true;
151	              if (dialogContext.mounted) {
152	                Navigator.of(dialogContext).pop();
153	              }
154	              if (!context.mounted) {
155	                return;
156	              }
157	              Navigator.of(context).push(
158	                MaterialPageRoute(
159	                  builder: (_) => const _BiometricReauthPlaceholder(),
160	                ),
161	              );
162	            },
163	          ),
164	        ),
165	      );
166	    });
167	  }
168	
169	  // `catchError`'s handler must still complete the Future with a value of
170	  // its declared type (`Either<Failure, Unit>`) — a `void`-returning
171	  // handler would try to complete it with `null`, which isn't assignable
172	  // to that non-nullable type and would itself throw.
173	  static Either<Failure, Unit> _asUnauthenticated(
174	    Object error,
175	    StackTrace stackTrace,
176	  ) {
177	    debugPrint('CerneApp: restoreSession() threw unexpectedly ($error)');
178	    return left(Failure.malformedResponse(message: error.toString()));
179	  }
180	
181	  @override
182	  Widget build(BuildContext context) {
183	    return MaterialApp(
184	      debugShowCheckedModeBanner: false,
185	      home: StreamBuilder<SessionStatus>(
186	        stream: _statusStream,
187	        builder: (context, snapshot) {
188	          if (!snapshot.hasData) {
189	            // No emission yet: brief-blank for the happy path (RNF01's
190	            // 300ms threshold) — `_BootLoadingScreen` only surfaces a
191	            // spinner once the wait actually crosses that.
192	            return const _BootLoadingScreen();
193	          }
194	          // Story 1.5: `expired` renders the exact same screen as
195	          // `authenticated` — the recovery overlay is layered on top
196	          // (scheduled below) instead of this branch ever returning a
197	          // different widget for it (Boundaries: "the authenticated
198	          // screen's widget instance is never replaced across
199	          // authenticated<->expired transitions").
200	          if (snapshot.data == SessionStatus.authenticated ||
201	              snapshot.data == SessionStatus.expired) {
202	            _maybeShowExpiryOverlay(context, snapshot.data);
203	            return const _PostAuthPlaceholder();
204	          }
205	          return AuthScreen(
206	            cubit: sl<AuthCubit>(),
207	            onAuthenticated: (context) => Navigator.of(context).pushReplacement(
208	              MaterialPageRoute(builder: (_) => const _PostAuthPlaceholder()),
209	            ),
210	          );
211	        },
212	      ),
213	    );
214	  }
215	}
216	
