238	class _BiometricReauthPlaceholder extends StatelessWidget {
239	  const _BiometricReauthPlaceholder();
240	
241	  @override
242	  Widget build(BuildContext context) {
243	    return Scaffold(
244	      backgroundColor: DesignTokens.colorSurfaceBg,
245	      body: const Center(
246	        child: Text('Biometria', style: DesignTokens.textHeadlineMd),
247	      ),
248	    );
249	  }
250	}
