import 'dart:async';

import 'package:flutter/material.dart';
import 'package:fpdart/fpdart.dart' hide State;

import 'core/design_tokens.dart';
import 'core/di/injection_container.dart';
import 'core/failure/failure.dart';
import 'core/widgets/confirmation_dialog.dart';
import 'features/auth/domain/entities/session_status.dart';
import 'features/auth/domain/repositories/session_repository.dart';
import 'features/auth/presentation/cubit/auth_cubit.dart';
import 'features/auth/presentation/screens/auth_screen.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  try {
    await setupCoreDependencies();
  } catch (error) {
    debugPrint(
      'Cerne failed to start: could not load .env ($error). Copy '
      '.env.example to .env and fill in FUNCTIONS_BASE_URL + '
      'SUPABASE_ANON_KEY before running the app.',
    );
    rethrow;
  }
  runApp(const CerneApp());
}

/// Root widget. Portrait-only, light-mode-only, fixed 390x844 frame — no
/// breakpoint, landscape or dark-mode path anywhere in the app (per the
/// epic's UX constraints).
///
/// Story 1.4 scope: `home` branches on `SessionRepository.statusStream`
/// instead of hardcoding `AuthScreen` — `restoreSession()` fires once at
/// boot (unconditional, no client-side expiry math) and the stream's first
/// emission decides whether the user lands on `AuthScreen` or the post-auth
/// placeholder. No `go_router` yet (Story 1.6): the `MaterialApp`/`Navigator`
/// shape is unchanged, and a successful signup/login still simply
/// pushes-replaces via `onAuthenticated`.
///
/// Story 1.5 scope: a mid-session expiry (the same stream's `expired`
/// value) never changes which screen `home` renders — `build()`'s
/// `StreamBuilder` branch below treats it identically to `authenticated`.
/// The only extra reaction is scheduling the `ConfirmationDialog` overlay
/// on top of that same screen, from inside that same (sole) subscription —
/// `SessionRepository.statusStream`'s real implementation is a broadcast
/// `Stream.multi`, but several existing tests mock it as a plain
/// single-subscription `Stream.value(...)`, so a *second* independent
/// `.listen()` here would break those by listening to it twice.
class CerneApp extends StatefulWidget {
  const CerneApp({super.key});

  @override
  State<CerneApp> createState() => _CerneAppState();
}

class _CerneAppState extends State<CerneApp> {
  late final SessionRepository _sessionRepository;

  // Cached once: `SessionRepository.statusStream`'s getter builds a new
  // `Stream.multi` instance on every access (code review of
  // story-1-4-silent-session-refresh-persistence), so reading it straight
  // into `StreamBuilder.stream` on every `build()` would make it resubscribe
  // and lose its current status on each rebuild instead of staying on one
  // subscription for this widget's lifetime.
  late final Stream<SessionStatus> _statusStream;

  // Code review of story-1-5: `ConfirmationDialog.isOpen` only guards
  // against a *second* overlay stacking while one is already showing — it
  // goes back to `false` the moment the first one closes. Nothing today
  // transitions `SessionStatus` away from `expired` once it's reached, so
  // without this separate flag, any later rebuild of `CerneApp` that still
  // observes `expired` (e.g. a hot reload, or a future dependency this
  // widget picks up) would call `ConfirmationDialog.show` again and reopen
  // the overlay on top of whatever the user already navigated to after
  // confirming it once.
  bool _expiryOverlayShown = false;

  // One-shot guard for the overlay's own "Entrar novamente" confirm callback
  // (code review of story-1-5) — a rapid double-tap during the dialog's
  // 180ms exit fade must not fire the pop/push pair twice.
  bool _reauthRouteRequested = false;

  @override
  void initState() {
    super.initState();
    _sessionRepository = sl<SessionRepository>();
    _statusStream = _sessionRepository.statusStream;
    // Fire-and-forget: the outcome reaches the UI through `statusStream`
    // below, not through this call's return value. `restoreSession()`
    // already maps every internal failure to `Left`/an `unauthenticated`
    // emission and never throws. This `catchError` is NOT a UI recovery
    // path — its handler's return value is discarded by `unawaited` and
    // never reaches `statusStream`, so it does not unblock `build()`'s
    // `_BootLoadingScreen` branch. It exists purely so a future regression
    // that broke the "never throws" contract above would surface as a
    // logged message instead of an unhandled zone exception.
    unawaited(
      _sessionRepository.restoreSession().catchError(_asUnauthenticated),
    );
  }

  /// Story 1.5's whole reaction to an `expired` snapshot (I/O matrix —
  /// every other status is a no-op, since `SessionRepositoryImpl` already
  /// only ever emits `expired` from `authenticated`, and this is called
  /// from the same `StreamBuilder` subscription that renders the screen,
  /// not a second one).
  ///
  /// `showGeneralDialog` (inside `ConfirmationDialog.show`) pushes a route,
  /// which must never happen mid-`build()` — deferred to
  /// `addPostFrameCallback`. `_expiryOverlayShown` (not
  /// `ConfirmationDialog.isOpen`, which resets as soon as the overlay
  /// closes) makes this a one-shot per `expired` episode: nothing today
  /// transitions the status back out of `expired`, so without that guard a
  /// later rebuild would reopen an overlay the user already confirmed.
  void _maybeShowExpiryOverlay(BuildContext context, SessionStatus? status) {
    if (status != SessionStatus.expired || _expiryOverlayShown) {
      return;
    }
    _expiryOverlayShown = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!context.mounted) {
        return;
      }
      // Discarded deliberately, same as `restoreSession()`'s own call above —
      // any error surfaces as a logged message instead of an unhandled
      // Future rejection.
      unawaited(
        ConfirmationDialog.show(
          context: context,
          builder: (dialogContext) => ConfirmationDialog(
            icon: Icons.lock_outline,
            title: 'Sessão expirada',
            message:
                'Sua sessão expirou por segurança. Entre novamente para '
                'continuar — sua conversa continua aqui.',
            caption: 'o histórico e a posição do scroll são preservados',
            confirmLabel: 'Entrar novamente',
            barrierColor: DesignTokens.colorScrim,
            onConfirm: () {
              // One-shot guard against a rapid double-tap firing this twice
              // while the dialog's 180ms exit fade still leaves the button
              // hit-testable — without it, a second tap would race the
              // first `pop()`/`push()` pair and could push a duplicate
              // `_BiometricReauthPlaceholder`.
              if (_reauthRouteRequested) {
                return;
              }
              _reauthRouteRequested = true;
              if (dialogContext.mounted) {
                Navigator.of(dialogContext).pop();
              }
              if (!context.mounted) {
                return;
              }
              Navigator.of(context).push(
                MaterialPageRoute(
                  builder: (_) => const _BiometricReauthPlaceholder(),
                ),
              );
            },
          ),
        ),
      );
    });
  }

  // `catchError`'s handler must still complete the Future with a value of
  // its declared type (`Either<Failure, Unit>`) — a `void`-returning
  // handler would try to complete it with `null`, which isn't assignable
  // to that non-nullable type and would itself throw.
  static Either<Failure, Unit> _asUnauthenticated(
    Object error,
    StackTrace stackTrace,
  ) {
    debugPrint('CerneApp: restoreSession() threw unexpectedly ($error)');
    return left(Failure.malformedResponse(message: error.toString()));
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      home: StreamBuilder<SessionStatus>(
        stream: _statusStream,
        builder: (context, snapshot) {
          if (!snapshot.hasData) {
            // No emission yet: brief-blank for the happy path (RNF01's
            // 300ms threshold) — `_BootLoadingScreen` only surfaces a
            // spinner once the wait actually crosses that.
            return const _BootLoadingScreen();
          }
          // Story 1.5: `expired` renders the exact same screen as
          // `authenticated` — the recovery overlay is layered on top
          // (scheduled below) instead of this branch ever returning a
          // different widget for it (Boundaries: "the authenticated
          // screen's widget instance is never replaced across
          // authenticated<->expired transitions").
          if (snapshot.data == SessionStatus.authenticated ||
              snapshot.data == SessionStatus.expired) {
            _maybeShowExpiryOverlay(context, snapshot.data);
            return const _PostAuthPlaceholder();
          }
          return AuthScreen(
            cubit: sl<AuthCubit>(),
            onAuthenticated: (context) => Navigator.of(context).pushReplacement(
              MaterialPageRoute(builder: (_) => const _PostAuthPlaceholder()),
            ),
          );
        },
      ),
    );
  }
}

/// Throwaway placeholder — Story 1.6 replaces this wholesale with the real
/// base navigation shell. Exists only so Story 1.3 has somewhere to land
/// after a successful signup/login.
class _PostAuthPlaceholder extends StatelessWidget {
  const _PostAuthPlaceholder();

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: DesignTokens.colorSurfaceBg,
      body: const Center(
        child: Text('Autenticado', style: DesignTokens.textHeadlineMd),
      ),
    );
  }
}

/// Throwaway placeholder — Epic 2's biometric/PIN re-auth flow deletes this
/// wholesale (Boundaries: "Entrar novamente" only navigates to a throwaway
/// placeholder that Epic 2 deletes wholesale"). Exists only so Story 1.5's
/// overlay has somewhere to route to.
class _BiometricReauthPlaceholder extends StatelessWidget {
  const _BiometricReauthPlaceholder();

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: DesignTokens.colorSurfaceBg,
      body: const Center(
        child: Text('Biometria', style: DesignTokens.textHeadlineMd),
      ),
    );
  }
}

/// Shown while `statusStream` has no data yet. Blank for the happy path
/// (RNF01: no loading UI below 300ms), but surfaces a centered spinner once
/// the wait crosses that threshold — `auth-refresh` is retried by
/// `RetryInterceptor` on `NETWORK_TIMEOUT`/`NETWORK_OFFLINE`, so a slow or
/// offline boot could otherwise leave the screen looking frozen for several
/// seconds with zero feedback. Kept as a private, inline, one-off widget
/// (no new shared-widget param) — same minimal-treatment convention Story
/// 1.3's submit button uses for its own >300ms affordance.
class _BootLoadingScreen extends StatefulWidget {
  const _BootLoadingScreen();

  @override
  State<_BootLoadingScreen> createState() => _BootLoadingScreenState();
}

class _BootLoadingScreenState extends State<_BootLoadingScreen> {
  static const _threshold = Duration(milliseconds: 300);

  bool _showIndicator = false;
  Timer? _timer;

  @override
  void initState() {
    super.initState();
    _timer = Timer(_threshold, () {
      if (mounted) {
        setState(() => _showIndicator = true);
      }
    });
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: DesignTokens.colorSurfaceBg,
      body: Center(
        child: _showIndicator
            ? const CircularProgressIndicator(color: DesignTokens.colorPrimary)
            : const SizedBox.shrink(),
      ),
    );
  }
}

import 'package:flutter/widgets.dart';

/// RNF08 — the single source of truth for every color, font, spacing and
/// radius literal in the app. No other file may hardcode a visual value.
///
/// Implemented verbatim from `docs/input/prototype/prototype-extract.md`
/// section 3 (colors, typography, spacing, radii, elevation) — see Story
/// 1.2's Design Notes for the handful of gaps that section leaves silent
/// (shared widget padding, avatar sizes, text-field border widths).
class DesignTokens {
  const DesignTokens._();

  // ---------------------------------------------------------------------
  // Colors — prototype-extract.md §3 "Colors"
  // ---------------------------------------------------------------------

  /// Buttons, app bar, wordmark.
  static const Color colorPrimary = Color(0xFF1F3D34);

  /// Pressed state.
  static const Color colorPrimaryPressed = Color(0xFF16281F);

  /// Text on primary.
  static const Color colorOnPrimary = Color(0xFFF5F1E8);

  /// CTA, insight, saved bookmark.
  static const Color colorAccent = Color(0xFFC98A3E);

  /// Text on accent.
  static const Color colorOnAccent = Color(0xFF241C0D);

  /// Tags, chips, synchronizing.
  static const Color colorSecondary = Color(0xFF7C8B6F);

  /// General background ("paper").
  static const Color colorSurfaceBg = Color(0xFFF2EFE7);

  /// Cards, bubbles, sheets.
  static const Color colorSurfaceElevated = Color(0xFFFBF9F4);

  /// Dividers, borders.
  static const Color colorBorder = Color(0xFFE1DACB);

  /// Main text.
  static const Color colorTextPrimary = Color(0xFF241F19);

  /// Secondary text.
  static const Color colorTextSecondary = Color(0xFF6B6255);

  /// Errors, destructive action.
